  `TWIN_ID` varchar(32) DEFAULT NULL COMMENT '트윈 아이디',
  `TWIN_OBJ_ID` varchar(32) DEFAULT NULL COMMENT '트윈 오브젝트 아이디',
  PRIMARY KEY (`AUGMENT_SEQ`),
